const sources = chunks
  .map((c, i) => `[${i + 1}] ${c.title}\n${c.text}`)
  .join('\n\n');

const prompt = `Answer from the sources only.
Cite each claim as [n].
If the sources do not say, answer "not found".

${sources}

Question: ${query}`;

// lists: arrays of chunk ids, best first
const rrf = (lists, k = 60) => {
  const score = new Map();
  for (const list of lists) {
    list.forEach((id, rank) => {
      const add = 1 / (k + rank + 1);
      score.set(id, (score.get(id) ?? 0) + add);
    });
  }
  return [...score.entries()]
    .sort((a, b) => b[1] - a[1])
    .map(([id]) => id);
};

const chunk = (tokens, size = 512, overlap = 64) => {
  const step = size - overlap;
  const chunks = [];
  for (let i = 0; i < tokens.length; i += step) {
    chunks.push(tokens.slice(i, i + size));
    if (i + size >= tokens.length) break;
  }
  return chunks;
};

// run: { ranked: [ids], relevant: Set of ids }
const recallAt = (k) => ({ ranked, relevant }) =>
  ranked.slice(0, k).filter((id) => relevant.has(id)).length
  / relevant.size;

const rr = ({ ranked, relevant }) => {
  const i = ranked.findIndex((id) => relevant.has(id));
  return i < 0 ? 0 : 1 / (i + 1);
};
